// Generated by supie __VERSION__ for the __NAME__ function. Do not edit: change
// the Python source and run `supie build`.
//
// Boots the Python runtime once per worker, loads the handler files into it,
// and passes each request to supie as JSON.

import { files, binaryFiles, entry } from "./app.ts";
import { loadPython } from "./python.ts";

const NAME = "__NAME__";
const here = `${import.meta.dirname ?? new URL(".", import.meta.url).pathname}/`
  .replace(/\/+$/, "/");

const decodeBase64 = (text: string) => Uint8Array.from(atob(text), (c) => c.charCodeAt(0));
const encodeBase64 = (bytes: Uint8Array) => {
  let binary = "";
  for (let i = 0; i < bytes.length; i += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  }
  return btoa(binary);
};

// What Python can call: environment variables and fetch, with every value
// passed as a string so both runtimes convert them the same way.
const host = {
  env: (name: string) => Deno.env.get(name) ?? null,
  fetch: async (
    url: string,
    method: string,
    headersJson: string,
    body: string | null,
    bodyBase64: boolean,
    wantBase64: boolean,
  ) => {
    const payload = body == null ? undefined : bodyBase64 ? decodeBase64(body) : body;
    const response = await fetch(url, { method, headers: JSON.parse(headersJson), body: payload });
    const text = wantBase64
      ? encodeBase64(new Uint8Array(await response.arrayBuffer()))
      : await response.text();
    return JSON.stringify({
      status: response.status,
      headers: Object.fromEntries(response.headers),
      body: text,
    });
  },
};

// Concurrency for supie.app.gather and wait_for: Python hands over coroutines,
// which both runtimes turn into thenables, and gets None back. Plus random IDs
// from the platform's CSPRNG.
Object.assign(host, {
  gather: (...tasks: Promise<unknown>[]) => Promise.all(tasks).then(() => null),
  race: (...tasks: Promise<unknown>[]) => Promise.race(tasks).then(() => null),
  sleep: (ms: number) => new Promise((resolve) => setTimeout(() => resolve(null), ms)),
  uuid: () => crypto.randomUUID().replaceAll("-", ""),
});

const t0 = performance.now();
const py = await loadPython(here);
py.registerJsModule("_supie_host", host);
for (const [path, text] of Object.entries(files)) py.writeFile(`/app/${path}`, text);
for (const [path, data] of Object.entries(binaryFiles)) {
  py.writeFile(`/app/${path}`, decodeBase64(data));
}
py.run(`
import sys
if "/app" not in sys.path:
    sys.path.insert(0, "/app")
import _supie_host
import supie.app as _supie_runtime
_supie_runtime.set_host(_supie_host)
import ${entry} as _supie_entry

def _supie_dispatch(raw):
    return _supie_runtime.dispatch(_supie_entry.app, raw)

def _supie_background(task_id):
    return _supie_runtime.run_background(task_id)
`);
const dispatch = py.get("_supie_dispatch");
const runBackground = py.get("_supie_background");
console.log(JSON.stringify({
  event: "supie.boot",
  function: NAME,
  runtime: py.runtime,
  boot_ms: +(performance.now() - t0).toFixed(1),
}));

// Requests arrive as /<name>/... or /functions/v1/<name>/...; handlers see
// only the part after the function name.
const routePath = (pathname: string) => {
  const parts = pathname.split("/").filter(Boolean);
  if (parts[0] === "functions" && parts[1] === "v1") parts.splice(0, 2);
  if (parts[0] === NAME) parts.shift();
  return "/" + parts.join("/");
};

const waitUntil = (promise: Promise<unknown>) => {
  const runtime = (globalThis as { EdgeRuntime?: { waitUntil(p: Promise<unknown>): void } })
    .EdgeRuntime;
  if (runtime) runtime.waitUntil(promise);
};

Deno.serve(async (req: Request) => {
  const url = new URL(req.url);
  const raw = JSON.stringify({
    method: req.method,
    path: routePath(url.pathname),
    query: Object.fromEntries(url.searchParams),
    headers: Object.fromEntries(req.headers),
    body: req.body ? await req.text() : "",
  });
  let wire;
  try {
    wire = JSON.parse(await dispatch(raw));
  } catch (err) {
    console.error(`supie: ${NAME} failed outside the handler:`, err);
    return Response.json({ error: "Internal Server Error" }, { status: 500 });
  }
  if (wire.log) console.error(wire.log);
  if (wire.bg != null) {
    waitUntil(
      Promise.resolve(runBackground(wire.bg)).then((log: string) => {
        if (log) console.error(log);
      }),
    );
  }
  const noBody = wire.status === 204 || wire.status === 304 || req.method === "HEAD";
  const body = noBody ? null : wire.base64 ? decodeBase64(wire.body) : wire.body;
  return new Response(body, { status: wire.status, headers: wire.headers });
});
